fn all_elements_equals(arr: &Vec<i32>, element: i32) -> bool {
    // Iterate through the array and check if every element equals `element`.
    // For an empty array, `.all(...)` returns true by vacuous truth.
    arr.iter().all(|&x| x == element)
}

